88: - [ ] **Step 3: 写实现**
89: 
90: ```ts
91: // uninstallTarget.ts
92: /** Minimal shape needed from PluginSummary to decide uninstall. */
93: export interface UninstallablePlugin {
94:   name: string;
95:   installKey: string;
96:   marketplace: string | null;
97: }
98: 
99: export type UninstallTarget =
100:   | { uninstallable: false }
101:   | { uninstallable: true; pluginName: string; marketplaceName: string };
102: 
103: /**
104:  * core's uninstallPlugin(pluginName, marketplaceName) requires a marketplace.
105:  * Plugins installed locally or via direct GitHub (marketplace === null) have
106:  * no marketplace key and cannot be uninstalled through this path.
107:  */
108: export function resolveUninstallTarget(p: UninstallablePlugin): UninstallTarget {
109:   if (!p.marketplace) return { uninstallable: false };
110:   const at = p.installKey.lastIndexOf("@");
111:   const pluginName = at > 0 ? p.installKey.slice(0, at) : p.installKey;
112:   const marketplaceName = at > 0 ? p.installKey.slice(at + 1) : p.marketplace;
113:   return { uninstallable: true, pluginName, marketplaceName };
114: }
115: ```
